insert into auth.users(id,email,email_confirmed_at)values(tests.id(960001),'barrier@example.test',now());
insert into auth.sessions values(tests.id(960101),tests.id(960001));
insert into reda_patients(id,organization_id,clinician_id,display_name,auth_user_id)values(tests.id(960000),tests.org('dashboard-test'),tests.id(1),'Fictional barrier',tests.id(960001));
insert into private.reda_patient_profiles(patient_id,focus)values(tests.id(960000),'Fictional goal');
insert into reda_plans(id,patient_id,clinician_id,version,status,payload)values(tests.id(960010),tests.id(960000),tests.id(1),1,'active',jsonb_set(jsonb_set(tests.plan(8),'{exercises,0,dose,sets}','2'),'{exercises,0,dose,label}','"2 x 8"'));
create function tests.barrier_session(n int,plan uuid)returns void language sql as $$insert into reda_sessions(id,client_session_id,patient_id,plan_id,plan_version,status,started_at,completed_at,payload)select tests.id(n),tests.id(n),patient_id,id,version,'completed',now(),now(),'{"exercises":[{"exerciseId":"extension","status":"completed","roundsDone":1,"feedback":"okay"}]}'::jsonb from reda_plans where id=plan$$;
select tests.barrier_session(960020,tests.id(960010));
set role authenticated;select tests.login(960001,'aal1',960101);
select reda_submit_session_reflection(tests.id(960020),tests.id(960021),'{"barrier":"time","support":"no","exerciseId":null}');
select set_config('tests.loop',reda_patient_barriers(tests.id(960000))->0->>'id',false);
select tests.ok(reda_patient_barriers(tests.id(960000))->0->>'phase'='needs_context','time signal opens specific quick question');
select tests.denied('select reda_publish_barrier(current_setting(''tests.loop'')::uuid,tests.id(960022),''token'',tests.plan(8),''Patient cannot approve'',''A clinical change'',current_date+7)','42501','patient cannot approve a plan');
select tests.login(1,'aal2',103);select tests.workspace('dashboard-test');
select set_config('tests.loop_token',reda_dashboard_patient(tests.id(960000))->>'token',false);
select tests.ok(reda_dashboard_patient(tests.id(960000))->'workflow'->>'phase'='barrier_question','overview identifies the next actor as patient');
select tests.login(950002,'aal1',950102);
select tests.denied('select reda_patient_barriers(tests.id(960000))','42501','another patient cannot read barrier history');
select tests.denied('select reda_answer_barrier(current_setting(''tests.loop'')::uuid,tests.id(960023),''{"minutes":10}'')','42501','another patient cannot answer');
select tests.login(960001,'aal1',960101);
select tests.denied('select reda_answer_barrier(current_setting(''tests.loop'')::uuid,tests.id(960023),''{"minutes":10,"approved":true}'')','22023','extra fields cannot smuggle approval');
