select tests.denied('select reda_answer_barrier(current_setting(''tests.loop'')::uuid,tests.id(960023),''{"minutes":20}'')','23505','saved answer is immutable');
select tests.login(1,'aal2',103);
select tests.ok(reda_dashboard_patient(tests.id(960000))->>'token'<>current_setting('tests.loop_token'),'quick reply invalidates previously viewed evidence');
select tests.denied('select reda_publish_barrier(current_setting(''tests.loop'')::uuid,tests.id(960024),reda_dashboard_patient(tests.id(960000))->>''token'',tests.plan(8),''Reviewed fewer rounds'',''Your reviewed shorter plan'',current_date+7)','42501','publication gate also blocks linked intervention');
reset role;update reda_organizations set patient_delivery_enabled=true where id=tests.org('dashboard-test');
set role authenticated;select tests.login(1,'aal2',103);
select tests.denied('select reda_publish_barrier(current_setting(''tests.loop'')::uuid,tests.id(960024),current_setting(''tests.loop_token''),tests.plan(8),''Reviewed fewer rounds'',''Your reviewed shorter plan'',current_date+7)','40001','stale clinical evidence cannot approve the loop');
