select set_config('tests.loop_publish',reda_publish_barrier(current_setting('tests.loop')::uuid,tests.id(960024),current_setting('tests.loop_token2'),tests.plan(8),'Reviewed fewer rounds','Your reviewed shorter plan',current_date+7)::text,false);
select tests.ok(reda_publish_barrier(current_setting('tests.loop')::uuid,tests.id(960024),current_setting('tests.loop_token2'),tests.plan(8),'Reviewed fewer rounds','Your reviewed shorter plan',current_date+7)::text=current_setting('tests.loop_publish'),'lost publication receipt cannot create two versions');
