reset role;
select tests.ok(not has_table_privilege('authenticated','private.reda_barrier_loops','select'),'internal receipt and approvals are not directly exposed');
select tests.ok(not has_function_privilege('authenticated','private.reda_barrier_state(uuid)','execute'),'unchecked projection stays private');
